button, a, input { -webkit-tap-highlight-color: transparent; }
button, input { font: inherit; }
button, a { touch-action: manipulation; }
a { color: inherit; text-decoration: none; }
button:focus-visible, a:focus-visible { outline: 2px solid #967009; outline-offset: 4px; border-radius: 4px; }
.g-root { --g-font-family-sans: 'Inter', 'Helvetica Neue', Arial, sans-serif; --g-button-border-radius: 10px; --g-text-input-border-radius: 10px; }
.page { min-height: 100svh; display: flex; flex-direction: column; background: radial-gradient(ellipse at 50% 44%, #fff 0%, #f7f8fa 66%); }
.site-header { height: 104px; padding: 0 4.3%; display: flex; align-items: center; justify-content: space-between; }
.brand { display: inline-flex; align-items: center; gap: 10px; font-size: 26px; font-weight: 750; letter-spacing: -1.1px; }
.brand-ui { font-weight: 400; color: #777a80; margin-left: 4px; }
.site-header .g-button { color: #656970; font-size: 13px; }
.site-header .g-button__text { display: flex; align-items: center; gap: 8px; }
.main { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 36px 32px 18px; }
.login-card { width: 100%; max-width: 1056px; min-height: 606px; display: grid; grid-template-columns: 1fr 1fr; background: white; padding: 8px; border: 1px solid #e8e9eb; border-radius: 24px; box-shadow: 0 12px 40px -24px #3b42423b, 0 3px 6px -4px #3036370a; }
.form-panel { padding: 43px 53px 38px; }
.welcome-icon { display: flex; align-items: center; justify-content: center; width: 46px; height: 46px; background: #fff5cd; border: 1px solid #ffebad; border-radius: 14px; color: #62501d; margin-bottom: 26px; }
h1 { margin: 0; font-size: 30px; line-height: 1.23; font-weight: 650; letter-spacing: -1.1px; }
.form-subtitle { color: #82858b; font-size: 14px; line-height: 1.6; margin: 11px 0 31px; }
.field { margin-bottom: 21px; }
.field label { display: block; font-size: 13px; font-weight: 550; margin-bottom: 9px; }
.field .g-text-input { width: 100%; --g-text-input-border-color: #dedfe3; --g-text-input-background-color: #fff; }
.field .g-text-input__control { font-size: 14px; }
.field .g-text-input__control::placeholder { color: #a2a5ac; }
.field .g-text-input__content { min-height: 48px; }
.password-field { margin-bottom: 19px; }
.form-options { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 26px; }
.form-options .g-checkbox { font-size: 12px; color: #5d6066; }
.text-button { border: none; padding: 0; background: transparent; font-size: 12px; color: #5f6269; cursor: pointer; line-height: 1.5; }
.text-button:hover { color: #161719; text-decoration: underline; text-underline-offset: 3px; }
.login-button { height: 48px; font-weight: 600; --g-button-text-color: #282513; }
.login-button .g-button__text { display: flex; align-items: center; justify-content: center; gap: 12px; font-size: 14px; }
.access-note { margin-top: 29px; padding-top: 23px; border-top: 1px solid #eeeff1; display: flex; flex-direction: column; align-items: center; gap: 6px; font-size: 12px; color: #91949a; }
.access-note .text-button { display: inline-flex; align-items: center; gap: 3px; color: #555960; }
.form-notice { background: #fff8dc; color: #69591f; border: 1px solid #f2e6b9; padding: 12px; border-radius: 8px; font-size: 12px; line-height: 1.6; margin-top: 14px; }
.story-panel { background: #f3f3ed; border-radius: 17px; position: relative; overflow: hidden; min-width: 0; padding: 35px 38px 26px; display: flex; flex-direction: column; }
.story-panel::before { content: ''; position: absolute; inset: 0; pointer-events: none; opacity: .37; background-image: radial-gradient(#b5b7a7 .65px, transparent .65px); background-size: 14px 14px; mask-image: linear-gradient(#000, transparent 71%); }
.story-label { position: relative; display: flex; align-items: center; gap: 7px; font-size: 9px; letter-spacing: 1.65px; color: #75786b; font-weight: 550; }
.label-dot { width: 5px; height: 5px; background: #8a8d74; border-radius: 50%; }
.orbit-art { display: block; width: calc(100% + 62px); margin: -1px -31px -2px; height: 325px; flex-shrink: 0; }
.story-copy { position: relative; padding-left: 4px; }
.story-copy h2 { font-size: 35px; font-weight: 550; line-height: 1.15; margin: 0 0 15px; letter-spacing: -1.2px; }
.story-copy p { margin: 0; color: #7d8075; font-size: 13px; line-height: 1.75; }
.story-bottom { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-top: auto; padding-top: 30px; position: relative; }
.mini-brand { display: inline-flex; gap: 8px; align-items: center; color: #777a70; font-size: 10px; }
.story-dots { display: flex; gap: 5px; }
.story-dots i { width: 5px; height: 5px; border-radius: 50%; background: #d2d3c9; }
.story-dots i:first-child { width: 16px; border-radius: 4px; background: #777c65; }
.security-note { color: #a0a3aa; display: flex; align-items: center; gap: 6px; font-size: 11px; margin-top: 24px; }
.site-footer { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 35px 4.3% 29px; color: #94979e; font-size: 11px; }
.site-footer a { display: flex; align-items: center; gap: 5px; }
.site-footer a:hover { color: #42474e; }
.locale { display: flex; align-items: center; gap: 7px; }
.locale > span { font-size: 17px; line-height: 12px; }
.help-modal { width: min(420px, calc(100vw - 32px)); padding: 32px; border-radius: 18px; position: relative; }
.modal-close { position: absolute; right: 14px; top: 14px; }
.help-modal h2 { font-size: 23px; letter-spacing: -.5px; line-height: 1.3; }
.help-modal p { color: #72767c; line-height: 1.7; margin-bottom: 28px; }
@media (min-width: 1500px) { .login-card { max-width: 1120px; } .form-panel { padding-left: 66px; padding-right: 66px; } .story-panel { padding-left: 44px; padding-right: 44px; } }
@media (max-width: 960px) { .form-panel { padding-left: 30px; padding-right: 30px; } .story-panel { padding-left: 27px; padding-right: 27px; } .story-copy h2 { font-size: 31px; } .story-label { font-size: 8px; letter-spacing: 1.2px; } .orbit-art { height: 320px; } .form-options { gap: 7px; } .form-options .g-checkbox, .form-options .text-button { font-size: 11px; } }
@media (max-width: 700px) { .site-header { height: 88px; padding: 0 24px; } .brand { font-size: 23px; } .main { padding: 18px 20px 30px; } .login-card { max-width: 450px; display: block; min-height: 0; border-radius: 21px; } .form-panel { padding: 28px 24px 30px; } h1 { font-size: 28px; } .story-panel { display: none; } .form-subtitle { font-size: 13px; margin-bottom: 29px; } .form-options .g-checkbox, .form-options .text-button { font-size: 12px; } .welcome-icon { margin-bottom: 24px; } .security-note { font-size: 10px; text-align: center; gap: 5px; } .site-footer { padding: 15px 24px 25px; flex-wrap: wrap; font-size: 10px; } .site-footer a { order: 3; width: 100%; justify-content: center; padding-top: 6px; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation-duration: .01ms "'!important; transition-duration: .01ms !important; } }
EOF
npm run build'

/bin/bash -lc "cat > /tmp/gravity-check/check.mjs <<'EOF'
import {chromium} from './node_modules/playwright/index.mjs';
import assert from 'node:assert/strict';
const browser = await chromium.launch({headless:true});
const page = await browser.newPage({viewport:{width:1440,height:1000},deviceScaleFactor:1});
const errors=[];
page.on('pageerror', error=>errors.push(error.message));
await page.goto('http://localhost:5175');
await page.evaluate(()=>document.fonts.ready);
await page.screenshot({path:'/tmp/gravity-desktop.png',fullPage:true});
await page.getByRole('button',{name:'Войти',exact:true}).click();
await page.getByText('Введите email',{exact:true}).waitFor();
await page.getByText('Введите пароль',{exact:true}).waitFor();
assert.equal(await page.locator('#email').evaluate(el=>el===document.activeElement),true);
await page.locator('#email').fill('invalid');
await page.getByText('Проверьте адрес электронной почты',{exact:true}).waitFor();
await page.locator('#email').fill('hello@example.com');
await page.locator('#password').fill('sample-password');
await page.getByRole('button',{name:/показать пароль/i}).click();
assert.equal(await page.locator('#password').getAttribute('type'),'text');
await page.getByRole('button',{name:/скрыть пароль/i}).click();
assert.equal(await page.locator('#password').getAttribute('type'),'password');
await page.getByRole('checkbox',{name:'Запомнить меня'}).check();
assert.equal(await page.getByRole('checkbox').isChecked(),true);
await page.locator('#password').press('Enter');
await page.getByRole('status').waitFor();
await page.getByRole('button',{name:'Забыли пароль?'}).click();
await page.getByRole('heading',{name:'Восстановление доступа'}).waitFor();
await page.keyboard.press('Escape');
await page.getByRole('heading',{name:'Восстановление доступа'}).waitFor({state:'hidden'});
await page.getByRole('button',{name:'Нужна помощь?'}).click();
await page.getByRole('heading',{name:'Помощь со входом'}).waitFor();
await page.getByRole('button',{name:'Понятно'}).click();
for(const width of [1440,768,390,320]) {
 await page.setViewportSize({width,height:900});
 const sizes=await page.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth}));
 assert.ok(sizes.scroll<=sizes.width,"'`Horizontal overflow at ${width}: ${JSON.stringify(sizes)}`);
}
await page.setViewportSize({width:390,height:844});
await page.reload();
await page.screenshot({path:'"'/tmp/gravity-mobile.png',fullPage:true});
assert.deepEqual(errors,[]);
console.log('PASS: field validation, focus, password reveal, checkbox, submit, help dialogs, Escape, four responsive widths, no runtime errors');
await browser.close();
EOF"
